using System.ComponentModel.DataAnnotations; using Marina.Domain.Catalog; using Marina.Domain.Security; using Marina.Persistence.Data; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace Marina.Api.Controllers;
[ApiController,Authorize(Policy="StaffMfa"),Route("api/v1/admin/catalog"),Microsoft.AspNetCore.RateLimiting.EnableRateLimiting("admin")]
public sealed class AdminCatalogController(MarinaDbContext db):ControllerBase{
 public sealed record TranslationRequest([Required,MaxLength(10)]string Culture,[Required,MaxLength(240)]string Name,[MaxLength(4000)]string?Description);public sealed record VariantRequest(Guid?Id,[Required,MaxLength(80)]string Sku,[MaxLength(80)]string?Barcode,Guid?ColorId,Guid?SizeId,decimal Price,decimal?CompareAtPrice,int InitialStock,bool IsActive);public sealed record ProductRequest([Required,MaxLength(180)]string Slug,Guid CategoryId,Guid?BrandId,bool IsActive,bool IsFeatured,bool IsNewArrival,bool IsOffer,List<TranslationRequest>Translations,List<VariantRequest>Variants);public sealed record CategoryRequest([Required,MaxLength(160)]string Slug,Guid?ParentId,int SortOrder,bool IsActive,List<TranslationRequest>Translations);
 [HttpGet("products"),Authorize(Policy="Products.View")]public async Task<ActionResult>Products([FromQuery]string?search=null,[FromQuery]int page=1,[FromQuery]int pageSize=30){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Products.IgnoreQueryFilters().AsNoTracking();if(!string.IsNullOrWhiteSpace(search)){var term=search.Trim();q=q.Where(x=>x.Slug.Contains(term)||x.Translations.Any(t=>t.Name.Contains(term))||x.Variants.Any(v=>v.Sku.Contains(term)));}var total=await q.CountAsync();return Ok(new{items=await q.OrderByDescending(x=>x.CreatedUtc).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.Id,x.Slug,x.IsActive,x.IsFeatured,x.IsNewArrival,x.IsOffer,Name=x.Translations.Where(t=>t.Culture=="en").Select(t=>t.Name).FirstOrDefault(),Variants=x.Variants.Count}).ToListAsync(),page,pageSize,total});}
 [HttpGet("products/{id:guid}"),Authorize(Policy="Products.View")]public async Task<ActionResult>Product(Guid id){var item=await db.Products.AsNoTracking().Where(x=>x.Id==id).Select(x=>new{x.Id,x.Slug,x.CategoryId,x.BrandId,x.IsActive,x.IsFeatured,x.IsNewArrival,x.IsOffer,x.Translations,Variants=x.Variants.Select(v=>new{v.Id,v.Sku,v.Barcode,v.ColorId,v.SizeId,v.Price,v.CompareAtPrice,v.IsActive,v.Inventory.Quantity,v.Inventory.LowStockThreshold}),x.Images}).SingleOrDefaultAsync();return item is null?NotFound():Ok(item);}
 [HttpPost("products"),Authorize(Policy="Products.Create")]public async Task<ActionResult>CreateProduct(ProductRequest r){Validate(r);var product=new Product{Slug=r.Slug.Trim().ToLowerInvariant(),CategoryId=r.CategoryId,BrandId=r.BrandId,IsActive=r.IsActive,IsFeatured=r.IsFeatured,IsNewArrival=r.IsNewArrival,IsOffer=r.IsOffer};foreach(var t in r.Translations)product.Translations.Add(new ProductTranslation{Culture=Culture(t.Culture),Name=t.Name.Trim(),Description=t.Description?.Trim()??""});foreach(var v in r.Variants)product.Variants.Add(new ProductVariant{Sku=v.Sku.Trim().ToUpperInvariant(),Barcode=v.Barcode?.Trim(),ColorId=v.ColorId,SizeId=v.SizeId,Price=v.Price,CompareAtPrice=v.CompareAtPrice,IsActive=v.IsActive,Inventory=new Inventory{Quantity=v.InitialStock}});db.Products.Add(product);Audit("Products.Create",product.Id,new{product.Slug});await db.SaveChangesAsync();return CreatedAtAction(nameof(Product),new{id=product.Id},new{product.Id});}
 [HttpPut("products/{id:guid}"),Authorize(Policy="Products.Edit")]public async Task<IActionResult>UpdateProduct(Guid id,ProductRequest r){Validate(r);var product=await db.Products.Include(x=>x.Translations).Include(x=>x.Variants).ThenInclude(x=>x.Inventory).SingleOrDefaultAsync(x=>x.Id==id)??throw new KeyNotFoundException("Product not found.");var old=new{product.Slug,product.IsActive};product.Slug=r.Slug.Trim().ToLowerInvariant();product.CategoryId=r.CategoryId;product.BrandId=r.BrandId;product.IsActive=r.IsActive;product.IsFeatured=r.IsFeatured;product.IsNewArrival=r.IsNewArrival;product.IsOffer=r.IsOffer;db.ProductTranslations.RemoveRange(product.Translations);product.Translations.Clear();foreach(var t in r.Translations)product.Translations.Add(new ProductTranslation{Culture=Culture(t.Culture),Name=t.Name.Trim(),Description=t.Description?.Trim()??""});foreach(var input in r.Variants){var variant=input.Id.HasValue?product.Variants.SingleOrDefault(x=>x.Id==input.Id):null;if(variant is null){product.Variants.Add(new ProductVariant{Sku=input.Sku.Trim().ToUpperInvariant(),Barcode=input.Barcode?.Trim(),ColorId=input.ColorId,SizeId=input.SizeId,Price=input.Price,CompareAtPrice=input.CompareAtPrice,IsActive=input.IsActive,Inventory=new Inventory{Quantity=input.InitialStock}});}else{variant.Sku=input.Sku.Trim().ToUpperInvariant();variant.Barcode=input.Barcode?.Trim();variant.ColorId=input.ColorId;variant.SizeId=input.SizeId;variant.Price=input.Price;variant.CompareAtPrice=input.CompareAtPrice;variant.IsActive=input.IsActive;}}Audit("Products.Edit",product.Id,old);await db.SaveChangesAsync();return NoContent();}
 [HttpDelete("products/{id:guid}"),Authorize(Policy="Products.Delete")]public async Task<IActionResult>DeleteProduct(Guid id){var p=await db.Products.SingleOrDefaultAsync(x=>x.Id==id)??throw new KeyNotFoundException("Product not found.");p.IsDeleted=true;p.IsActive=false;Audit("Products.Delete",p.Id,new{p.Slug});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("categories"),Authorize(Policy="Products.View")]public async Task<ActionResult>Categories()=>Ok(await db.Categories.AsNoTracking().OrderBy(x=>x.SortOrder).Select(x=>new{x.Id,x.ParentId,x.Slug,x.SortOrder,x.IsActive,x.Translations}).ToListAsync());
 [HttpPost("categories"),Authorize(Policy="Products.Create")]public async Task<ActionResult>CreateCategory(CategoryRequest r){if(r.Translations.Count==0)throw new ArgumentException("A translation is required.");var c=new Category{Slug=r.Slug.Trim().ToLowerInvariant(),ParentId=r.ParentId,SortOrder=r.SortOrder,IsActive=r.IsActive,Translations=r.Translations.Select(t=>new CategoryTranslation{Culture=Culture(t.Culture),Name=t.Name.Trim()}).ToList()};db.Categories.Add(c);await db.SaveChangesAsync();return Created("",new{c.Id});}
 [HttpGet("brands"),Authorize(Policy="Products.View")]public async Task<ActionResult>Brands()=>Ok(await db.Brands.AsNoTracking().Where(x=>!x.IsDeleted).Select(x=>new{x.Id,x.Slug,x.IsActive,x.Translations}).ToListAsync());
 private static void Validate(ProductRequest r){if(r.Translations.Count==0||r.Variants.Count==0||r.Translations.Select(x=>Culture(x.Culture)).Distinct().Count()!=r.Translations.Count||r.Variants.Any(x=>x.Price<0||x.InitialStock<0))throw new ArgumentException("Invalid product data.");}private static string Culture(string value)=>value.Equals("ar",StringComparison.OrdinalIgnoreCase)?"ar":"en";private void Audit(string action,Guid id,object value)=>db.AuditLogs.Add(new AuditLog{Action=action,EntityName="Product",EntityId=id.ToString(),IpAddress=HttpContext.Connection.RemoteIpAddress?.ToString()??"unknown",CorrelationId=HttpContext.TraceIdentifier,NewValuesJson=System.Text.Json.JsonSerializer.Serialize(value)});
}
